 on($(ids.select),'change',()=>{const id=$(ids.select).value;profileAction(async()=>{const next=structuredClone(apiProfiles);next[ids.active]=id;await persistProfiles(next);if(dead)return;invalidateTranslation();renderProfiles();fillApiProfile(kind,next[kind].find(p=>p.id===id));status(id?'已切换接口。':'新接口。');});});
