let dbPromise=null,historyRows=[],historyRenderToken=0,historyUrl='',historyCurrentId=null,historyDb=null;
function openHistory(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{if(!W.indexedDB)return reject(Error('浏览器未提供本地录音存储。'));const req=W.indexedDB.open('lili-voice-history',2);req.onupgradeneeded=()=>{const db=req.result;for(const name of ['records','audio','songs'])if(!db.objectStoreNames.contains(name))db.createObjectStore(name,{keyPath:'id'});};req.onerror=()=>reject(req.error||Error('无法打开录音存储。'));req.onblocked=()=>status('存储被其他酒馆页面占用，请关闭其他页面后重试。');req.onsuccess=()=>{historyDb=req.result;if(dead){historyDb.close();return reject(Error('配音室已关闭。'));}historyDb.onversionchange=()=>{historyDb.close();historyDb=null;dbPromise=null;};resolve(historyDb);};}).catch(e=>{dbPromise=null;throw e;});return dbPromise;}
async function historyTx(names,mode,work){const db=await openHistory();return new Promise((resolve,reject)=>{const tx=db.transaction(names,mode);let value;tx.oncomplete=()=>resolve(typeof value==='function'?value():value);tx.onerror=()=>reject(tx.error||Error('录音存储失败。'));tx.onabort=()=>reject(tx.error||Error('录音存储已取消。'));try{value=work(tx);}catch(e){tx.abort();reject(e);}});}
