async function historyBlob(id){const entry=await historyTx(['audio'],'readonly',tx=>{const req=tx.objectStore('audio').get(id);return ()=>req.result;});if(!entry?.bytes)throw Error('这段录音的数据不存在。');return new W.Blob([entry.bytes],{type:'audio/mpeg'});}
