const recordingName=row=>`${row.voiceName.replace(/[\\/:*?"<>|]/g,'_')}-${new Date(row.createdAt).toISOString().replace(/[:.]/g,'-')}.mp3`;
async function playHistory(row){stopMusic();stop();stopHistory();historyCurrentId=row.id;const blob=await historyBlob(row.id);if(dead||historyCurrentId!==row.id)return;historyUrl=W.URL.createObjectURL(blob);$('historyAudio').src=historyUrl;$('historyAudio').hidden=false;$('historyNow').textContent=`${row.voiceName} · ${row.text}`;try{await $('historyAudio').play();}catch{status('录音已载入，请点击播放器播放。');}}
