const downloadUrls=new Set();let historyLimit=25;
function firstSentence(text){return String(text||'').trim().match(/^[^。！？!?\n]+[。！？!?]?|^[\s\S]/)?.[0]||'空白录音';}
async function renderHistory(reset=true){const token=++historyRenderToken;try{const rows=await historyList();if(dead||token!==historyRenderToken)return;historyRows=rows.sort((a,b)=>b.createdAt-a.createdAt);if(reset)historyLimit=25;const filter=$('historyFilter'),chosen=filter.value;const groups=new Map();for(const row of historyRows){let g=groups.get(row.voiceGroup);if(!g)groups.set(row.voiceGroup,g={name:row.voiceName,voiceId:row.voiceId,count:0});g.count++;}filter.replaceChildren();const all=node('option',`全部音色 · ${historyRows.length} 条`);all.value='';filter.append(all);for(const [key,g] of groups){const o=node('option',`${g.name} · ${g.count} 条 (${g.voiceId})`);o.value=key;filter.append(o);}filter.value=groups.has(chosen)?chosen:'';const query=$('historySearch').value.trim().normalize('NFKC').toLocaleLowerCase();const selected=historyRows.filter(r=>(!filter.value||r.voiceGroup===filter.value)&&(!query||[r.text,r.voiceName,r.voiceId,new Date(r.createdAt).toLocaleString(),new Date(r.createdAt).toLocaleDateString('sv-SE')].join(' ').normalize('NFKC').toLocaleLowerCase().includes(query))),list=$('historyList');list.replaceChildren();$('historySummary').textContent=`已保存 ${historyRows.length} 条 · 找到 ${selected.length} 条 · ${(historyRows.reduce((n,r)=>n+r.size,0)/1024/1024).toFixed(1)} MB`;
if(!selected.length){list.append(node('p',query?'没有匹配的录音。':'还没有录音。'));}
for(const row of selected.slice(0,historyLimit)){const card=node('details',null,'lv-record');const title=node('summary');title.append(node('span',new Date(row.createdAt).toLocaleString(),'lv-record-date'),node('span',firstSentence(row.text),'lv-record-title'),node('span',row.voiceName,'lv-record-voice'));const info=node('p',`${new Date(row.createdAt).toLocaleString()} · ${languages.find(x=>x[0]===row.language)?.[1]||row.language}`);const words=node('p',row.text,'lv-record-text');const buttons=node('div',null,'lv-row');for(const [label,fn] of [['播放',()=>playHistory(row)],['下载',()=>downloadHistory(row)]]){const b=node('button',label);b.type='button';b.addEventListener('click',async()=>{b.disabled=true;try{await fn();}catch(e){status(safe(e.message));}finally{b.disabled=false;}});buttons.append(b);}const del=node('button','删除');del.type='button';const cancel=node('button','取消');cancel.type='button';cancel.hidden=true;let armed=false;cancel.addEventListener('click',()=>{armed=false;del.textContent='删除';cancel.hidden=true;});del.addEventListener('click',async()=>{if(!armed){armed=true;del.textContent='确认删除';cancel.hidden=false;return;}del.disabled=true;try{await deleteRecording(row.id);await renderHistory(false);status('这条录音已删除。');}catch(e){status(safe(e.message));del.disabled=false;}});buttons.append(del,cancel);card.append(title,info,words,buttons);list.append(card);}
$('historyMore').hidden=selected.length<=historyLimit;
}catch(e){if(!dead){$('historyList').replaceChildren(node('p','暂时无法读取存储。已有配音仍可直接下载。'));status(safe(e.message));}}}
